begin;
create table public.cloud_manga_inspection_runs(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.cloud_projects(id)on delete cascade,owner_profile_id uuid not null references public.profiles(id)on delete cascade,page_id uuid,panel_id uuid,asset_id uuid,generation_job_id uuid,panel_design_revision bigint check(panel_design_revision>0),schema_version integer not null default 1 check(schema_version=1),evaluator_id text not null check(char_length(evaluator_id)between 1 and 100),evaluator_version text not null check(char_length(evaluator_version)between 1 and 50),evaluator_kind text not null check(evaluator_kind in('rule','vision','hybrid')),data_handling text not null check(data_handling in('none','local','external')),input_snapshot jsonb not null default'{}'::jsonb check(jsonb_typeof(input_snapshot)='object'and pg_column_size(input_snapshot)<=131072),created_at timestamptz not null default now(),foreign key(page_id,project_id)references public.cloud_pages(id,project_id)on delete cascade);
create table public.cloud_manga_inspection_findings(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.cloud_manga_inspection_runs(id)on delete cascade,project_id uuid not null references public.cloud_projects(id)on delete cascade,owner_profile_id uuid not null references public.profiles(id)on delete cascade,page_id uuid,panel_id uuid,status text not null check(status in('PASS','WARNING','FAIL','NOT_EVALUATED')),category text not null check(category in('image_availability','image_resolution','character_count','character_identity','hair','costume','body_build','anatomy','background','prop','orientation','gaze','dialogue_speaker','text_layout','reading_order','composition_duplicate','continuity')),reason text not null check(char_length(reason)between 1 and 500),region jsonb check(region is null or(jsonb_typeof(region)='object'and region->>'kind'in('rectangle','polygon')and pg_column_size(region)<=8192)),confidence numeric(6,5) check(confidence between 0 and 1),suggestion text not null check(suggestion in('review','edit_text','regenerate_panel','inpaint','update_design','update_reference')),evidence jsonb not null default'{}'::jsonb check(jsonb_typeof(evidence)='object'and pg_column_size(evidence)<=32768),created_at timestamptz not null default now(),check((status='NOT_EVALUATED'and confidence is null)or(status<>'NOT_EVALUATED'and confidence is not null)),foreign key(page_id,project_id)references public.cloud_pages(id,project_id)on delete cascade);
create index cloud_manga_inspection_runs_project_idx on public.cloud_manga_inspection_runs(project_id,created_at desc);create index cloud_manga_inspection_findings_panel_idx on public.cloud_manga_inspection_findings(project_id,page_id,panel_id,status,created_at desc);
alter table public.cloud_manga_inspection_runs enable row level security;alter table public.cloud_manga_inspection_findings enable row level security;grant select on public.cloud_manga_inspection_runs,public.cloud_manga_inspection_findings to authenticated;grant select,insert on public.cloud_manga_inspection_runs,public.cloud_manga_inspection_findings to service_role;create policy "cloud_manga_inspection_runs_owner_read" on public.cloud_manga_inspection_runs for select using(owner_profile_id=public.current_profile_id()and public.cloud_project_can_edit(project_id));create policy "cloud_manga_inspection_findings_owner_read" on public.cloud_manga_inspection_findings for select using(owner_profile_id=public.current_profile_id()and public.cloud_project_can_edit(project_id));
create function public.record_cloud_manga_inspection_run(p_project_id uuid,p_page_id uuid,p_panel_id uuid,p_asset_id uuid,p_generation_job_id uuid,p_panel_design_revision bigint,p_evaluator jsonb,p_input_snapshot jsonb,p_findings jsonb)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare v_owner uuid;v_run uuid;v_finding jsonb;begin if auth.role()<>'service_role'then raise exception'service_role_required';end if;select owner_profile_id into v_owner from public.cloud_projects where id=p_project_id;if v_owner is null or(p_page_id is not null and not exists(select 1 from public.cloud_pages where id=p_page_id and project_id=p_project_id))or jsonb_typeof(p_evaluator)<>'object'or p_evaluator->>'kind'not in('rule','vision','hybrid')or p_evaluator->>'dataHandling'not in('none','local','external')or jsonb_typeof(p_findings)<>'array'or jsonb_array_length(p_findings)not between 1 and 100 then raise exception'cloud_manga_inspection_run_invalid';end if;insert into public.cloud_manga_inspection_runs(project_id,owner_profile_id,page_id,panel_id,asset_id,generation_job_id,panel_design_revision,evaluator_id,evaluator_version,evaluator_kind,data_handling,input_snapshot)values(p_project_id,v_owner,p_page_id,p_panel_id,p_asset_id,p_generation_job_id,p_panel_design_revision,p_evaluator->>'id',p_evaluator->>'version',p_evaluator->>'kind',p_evaluator->>'dataHandling',coalesce(p_input_snapshot,'{}'::jsonb))returning id into v_run;for v_finding in select value from jsonb_array_elements(p_findings)loop if v_finding->>'status'not in('PASS','WARNING','FAIL','NOT_EVALUATED')or nullif(trim(v_finding->>'reason'),'')is null or v_finding->>'suggestion'not in('review','edit_text','regenerate_panel','inpaint','update_design','update_reference')or(v_finding->>'status'='NOT_EVALUATED'and v_finding->'confidence'<>'null'::jsonb)or(v_finding->>'status'<>'NOT_EVALUATED'and jsonb_typeof(v_finding->'confidence')<>'number')then raise exception'cloud_manga_inspection_finding_invalid';end if;insert into public.cloud_manga_inspection_findings(run_id,project_id,owner_profile_id,page_id,panel_id,status,category,reason,region,confidence,suggestion,evidence)values(v_run,p_project_id,v_owner,p_page_id,p_panel_id,v_finding->>'status',v_finding->>'category',trim(v_finding->>'reason'),v_finding->'region',case when v_finding->>'status'='NOT_EVALUATED'then null else(v_finding->>'confidence')::numeric end,v_finding->>'suggestion',coalesce(v_finding->'evidence','{}'::jsonb));end loop;return v_run;end$$;
revoke all on function public.record_cloud_manga_inspection_run(uuid,uuid,uuid,uuid,uuid,bigint,jsonb,jsonb,jsonb)from public,anon,authenticated;grant execute on function public.record_cloud_manga_inspection_run(uuid,uuid,uuid,uuid,uuid,bigint,jsonb,jsonb,jsonb)to service_role;notify pgrst,'reload schema';
commit;
